/// <summary>
/// CB201 - Rebate aggregate transactions based on aggregator
/// </summary>
/// <param name = "_rebateJournalTrans"><t>TAMRebateJournalTrans</t></param>
/// <param name = "_rebateTrans"><t>TAMRebateTrans</t></param>
public static void setAggregatedStrOnJournalTrans(TAMRebateJournalTrans _rebateJournalTrans, TAMRebateTrans _rebateTrans)
{
    next setAggregatedStrOnJournalTrans(_rebateJournalTrans, _rebateTrans);

    // Set the aggregated string on the journal trans so that it can be used later when getting/creating rebate date transactions.
    _rebateJournalTrans.parmCurrentAggregatedStr(_rebateTrans.METAggregatedStr);
}
